const dashboardBase=dashboard;dashboard=function(){state.generation++;state.currentView='dashboard';if(state.area==='officer')return officerHome();setArea('academy');return dashboardBase.apply(this,arguments)};
const documentsBase=documentsView;newsView=()=>announcementView('news');documentsView=()=>announcementView('documents');
async function announcementView(view='news'){const token=header(view,view==='documents'?'Department-Dokumente & Mitteilungen':'Mitteilungen','Verbindliche Informationen aus dem Department.');try{await ready();await loadCore();if(token!==state.generation)return;const read=new Set(state.reads.map(r=>String(r.announcement_id)));root().querySelector('.hub-work').innerHTML=`${staff(current)?`<details class="hub-editor"><summary>Mitteilung veröffentlichen</summary><form id="hubAnnouncement" class="hub-form"><label>Titel<input name="title" required maxlength="150"></label><label class="hub-wide">Nachricht<textarea name="body" required maxlength="10000" rows="5"></textarea></label><label class="hub-check"><input type="checkbox" name="pinned"> Oben anheften</label><button type="submit" class="primary">Veröffentlichen</button></form></details>`:''}${view==='documents'?'<button class="secondary" type="button" data-old-documents>Handbuch, Favoriten & Vorlagen öffnen</button>':''}<div class="hub-announcements">${state.announcements.slice().sort((a,b)=>Number(b.pinned)-Number(a.pinned)||new Date(b.created_at)-new Date(a.created_at)).map(n=>`<article class="card"><div class="eyebrow">${n.pinned?'ANGEHEFTET · ':''}${E(date(n.created_at))}</div><h2>${E(n.title)}</h2><p class="hub-pre">${E(n.body)}</p><small>${E(n.author_name||'MRPD')}</small><div class="hub-announcement-actions">${read.has(String(n.id))?'<span class="hub-read-check">✓ Als gelesen markiert</span>':`<button class="secondary" data-ann-read="${n.id}">Als gelesen markieren</button>`}</div></article>`).join('')||'<section class="card"><p class="muted">Noch keine Mitteilungen.</p></section>'}</div>`;root().querySelector('[data-old-documents]')?.addEventListener('click',()=>documentsBase());root().querySelectorAll('[data-ann-read]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await rpc('announcement_read',{id:b.dataset.annRead});await loadCore();announcementView(view)}catch(e){tell(errorText(e));b.disabled=false}});bindForm(root().querySelector('#hubAnnouncement'),async f=>{const {error}=await sb.from('announcements').insert({title:f.title.trim(),body:f.body.trim(),pinned:f.pinned==='on',author_id:current.id,author_name:current.name});if(error)throw error;await loadCore();await announcementView(view)})}catch(e){showError(e,token)}}
function notifications(){const hidden=new Set(state.dismissals.map(d=>d.item_key)),read=new Map(state.reads.map(r=>[String(r.announcement_id),r]));const items=state.announcements.filter(n=>!read.get(String(n.id))?.dismissed_at).map(n=>({key:'announcement:'+n.id,id:String(n.id),kind:'announcement',title:n.title,body:n.body,when:n.created_at,read:!!read.get(String(n.id)),author:n.author_name}));for(const m of db.messages||[])if(m.recipient_id===current?.id&&!hidden.has('message:'+m.id))items.push({key:'message:'+m.id,id:m.id,kind:'message',title:m.subject,body:m.body,when:m.created_at,read:!!m.read_at,author:person(m.sender_id).name});for(const m of state.chatMessages.slice(-60))if(channelAccess(current,m.channel||'staff')&&m.author_id!==current.id&&!hidden.has('staff:'+m.id))items.push({key:'staff:'+m.id,id:m.id,kind:'staff',channel:m.channel||'staff',title:CHANNELS[m.channel||'staff'].title,body:m.body||(m.image_path?'Neues Bild':''),when:m.created_at,read:state.receipts.some(r=>r.message_id===m.id&&r.user_id===current.id),author:person(m.author_id).name});return items.sort((a,b)=>new Date(b.when)-new Date(a.when))}
const bellBase=installNotificationBell;installNotificationBell=function(){bellBase();updateBell()};
function updateBell(){const b=document.querySelector('.notify-btn');if(!b||!current)return;const n=notifications().filter(x=>!x.read).length;b.innerHTML=`<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5Zm5 3h4M12 2v2"/></svg>${n?`<i>${n}</i>`:''}`;b.title=`Benachrichtigungen · ${n} ungelesen`;b.setAttribute('aria-label',b.title)}
openWorkflowNotifications=async function(){if(!current)return;await ready().catch(e=>tell(errorText(e)));document.querySelector('.hub-notification-dialog')?.remove();const d=document.createElement('dialog');d.className='hub-dialog hub-notification-dialog';const items=notifications();d.innerHTML=`<header><h2>Benachrichtigungen</h2><button type="button" data-close aria-label="Schließen">×</button></header><p class="muted">Entfernen blendet nur deine Benachrichtigung aus. Die Mitteilung oder Nachricht bleibt im jeweiligen Bereich erhalten.</p><div class="hub-notification-list">${items.map((n,i)=>`<article class="${n.read?'':'unread'}"><small>${E(n.author||'Department')} · ${E(date(n.when))}</small><h3>${E(n.title)}</h3><p class="hub-pre">${E(n.body)}</p><div>${!n.read?`<button class="secondary" type="button" data-note-read="${i}">Als gelesen markieren</button>`:'<span class="hub-read-check">✓ Gelesen</span>'}<button class="secondary" type="button" data-note-open="${i}">Öffnen</button><button class="secondary" type="button" data-note-remove="${i}">Entfernen</button></div></article>`).join('')||'<p class="muted">Keine Benachrichtigungen.</p>'}</div>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();for(const b of d.querySelectorAll('[data-note-read],[data-note-remove]'))b.onclick=async()=>{b.disabled=true;const remove=b.dataset.noteRemove!==undefined,n=items[+(remove?b.dataset.noteRemove:b.dataset.noteRead)];try{if(n.kind==='announcement')await rpc('announcement_read',{id:n.id,dismiss:remove});else if(remove)await write('portal_hub_dismissals',{user_id:current.id,item_key:n.key});else if(n.kind==='message'){const {error}=await sb.from('academy_messages').update({read_at:new Date().toISOString()}).eq('id',n.id).eq('recipient_id',current.id);if(error)throw error;const m=db.messages.find(m=>m.id===n.id);if(m)m.read_at=new Date().toISOString()}else await markChatRead([n.id]);await loadCore();d.close();openWorkflowNotifications()}catch(e){tell(errorText(e));b.disabled=false}};d.querySelectorAll('[data-note-open]').forEach(b=>b.onclick=()=>{const n=items[+b.dataset.noteOpen];d.close();showView(n.kind==='staff'?CHANNELS[n.channel||'staff'].view:n.kind==='message'?'messages':'news')});d.showModal()};
async function unlockAudio(){try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')await audio.resume();audioReady=audio.state==='running'}catch{audioReady=false}}
function chime(force=false){if(!audioReady||(!force&&!state.settings.sound_enabled))return;const t=audio.currentTime;for(const [note,delay] of [[880,0],[1174.66,.13]]){const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=note;gain.gain.setValueAtTime(0,t+delay);gain.gain.linearRampToValueAtTime(.09,t+delay+.015);gain.gain.exponentialRampToValueAtTime(.001,t+delay+.55);osc.connect(gain);gain.connect(audio.destination);osc.start(t+delay);osc.stop(t+delay+.6)}}
document.addEventListener('pointerdown',()=>unlockAudio(),{once:true});
function subscribe(){state.subscriptions.forEach(c=>sb.removeChannel(c));state.subscriptions=[];const uid=current?.id;if(!uid)return;const channel=sb.channel('department-hub:'+uid);channel.on('postgres_changes',{event:'INSERT',schema:'public',table:'announcements'},event=>{if(event.new.author_id!==uid){tell('Neue Department-Mitteilung: '+event.new.title);chime()}scheduleRealtime('announcements')});channel.on('postgres_changes',{event:'INSERT',schema:'public',table:'academy_messages',filter:'recipient_id=eq.'+uid},event=>{if(event.new.sender_id!==uid){tell('Neue Nachricht im Postfach');chime()}scheduleRealtime('mail')});channel.on('postgres_changes',{event:'INSERT',schema:'public',table:'portal_hub_rank_changes'},()=>scheduleRealtime('rank'));if(allowedChannels(current).length){channel.on('postgres_changes',{event:'INSERT',schema:'public',table:'portal_hub_staff_messages'},event=>{if(!channelAccess(current,event.new.channel||'staff'))return;if(event.new.author_id!==uid){tell('Neue Nachricht im '+CHANNELS[event.new.channel||'staff'].title);chime()}scheduleRealtime('chat')});for(const table of ['portal_hub_staff_receipts','portal_hub_staff_reactions'])channel.on('postgres_changes',{event:'*',schema:'public',table},()=>scheduleRealtime('chat'))}channel.subscribe(status=>{if(status==='CHANNEL_ERROR')console.warn('Department-Liveverbindung unterbrochen. Beim erneuten Öffnen werden Nachrichten nachgeladen.');});state.subscriptions.push(channel)}
let pendingRealtime=new Set();function scheduleRealtime(kind){pendingRealtime.add(kind);clearTimeout(realtimeTimer);realtimeTimer=setTimeout(async()=>{const pending=new Set(pendingRealtime);pendingRealtime.clear();try{if(pending.has('rank')){await refreshData();subscribe();nav();if(isChatView(state.currentView)&&!channelAccess(current,state.chatChannel))return showView('officer-home');if(state.currentView==='rank-changes')rankView()}else if(pending.has('mail'))await refreshData();else await loadCore();if(allowedChannels(current).length&&pending.has('chat')){for(const key of allowedChannels(current))await chatData(false,key);if(isChatView(state.currentView))await renderChat()}updateBell()}catch(e){console.warn('Department-Update:',e.message)}},350)}
