window.APD_HUB={state,RANKS,canonical,rankIndex,staff,plus,chatAllowed,channelAccess,CHANNELS,setArea,loadCore,showView,notifications,compressImage};
sb.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){state.subscriptions.forEach(c=>sb.removeChannel(c));state.subscriptions=[];state.uid=null;state.ready=false;state.people=[];state.chatMessages=[];state.chatMore={};state.reactions=[];state.receipts=[];state.announcements=[];state.reads=[];state.dismissals=[];state.imageURLs.clear();state.currentView='';chatObserver?.disconnect();clearTimeout(realtimeTimer);state.generation++}});
